const isTravel=event=>['outbound','return'].includes(event.kind);
function periodFragments(period,trips){let fragments=[period];for(const trip of trips){fragments=fragments.flatMap(p=>trip.date<p.start||trip.date>p.end?[p]:[...(trip.date>p.start?[{...p,end:add(trip.date,-1)}]:[]),...(trip.date<p.end?[{...p,start:add(trip.date,1)}]:[])])}return fragments}
const eventLabels={outbound:'Поездка на объект',return:'Обратная поездка',arrival:'Прибытие',departure:'Отъезд',note:'Примечание'};
