const months=['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];
const dt=s=>new Date(s+'T12:00:00Z');
const iso=d=>d.toISOString().slice(0,10);
const add=(s,n)=>{let d=dt(s);d.setUTCDate(d.getUTCDate()+n);return iso(d)};
const fmt=s=>dt(s).toLocaleDateString('ru-RU',{timeZone:'UTC',day:'2-digit',month:'2-digit',year:'numeric'});
const short=s=>dt(s).toLocaleDateString('ru-RU',{timeZone:'UTC',day:'numeric',month:'short'});
const todayISO=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Vilnius',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const week=d=>{let t=new Date(d);t.setUTCDate(t.getUTCDate()+4-(t.getUTCDay()||7));let y=new Date(Date.UTC(t.getUTCFullYear(),0,1));return Math.ceil((((t-y)/86400000)+1)/7)};
const initials=e=>(e.first_name?.[0]||'')+(e.last_name?.[0]||'');
const fullName=e=>e.first_name+' '+e.last_name;
let appVersion=null,countryCatalog={};
function countryCode(value){const normalize=text=>String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLocaleLowerCase();const query=normalize(value);return Object.keys(countryCatalog).find(code=>[code,...countryCatalog[code],code+' · '+countryName(code)].some(label=>normalize(label)===query))||''}
function countryName(value){const names=countryCatalog[value];return names?names[{ru:0,lt:1,pl:2,en:3}[language]]:value||''}
function projectLocation(project){return [project.address,countryName(countryCode(project.country)||project.country)].filter(Boolean).join(', ')}
function countryInput(value){const code=countryCode(value),label=code?code+' · '+countryName(code):value||'';return `<label>Страна<input name="country" list="project-countries" required autocomplete="off" placeholder="Найти страну…" value="${esc(label)}"><datalist id="project-countries">${Object.keys(countryCatalog).sort((a,b)=>countryName(a).localeCompare(countryName(b),language)).map(code=>`<option value="${esc(code+' · '+countryName(code))}"></option>`).join('')}</datalist></label>`}

function versionBadge(){return appVersion?`<span class="version-badge">v${esc(appVersion)}</span>`:''}
let state=null,view='schedule',projectId=null,anchor=todayISO(),scale='month',search='',specialty='',status='active',csrf='',modalSubmit=null,modalActions={},lastFocus=null,toastTimer;
