try{const saved=localStorage.getItem('rotations-sidebar-collapsed');if(saved!==null)sidebarCollapsed=saved==='true'}catch{}
function sidebarToggle(){const label=sidebarCollapsed?'Развернуть меню':'Свернуть меню';return `<button class="sidebar-toggle" data-act="toggle-sidebar" title="${label}" aria-label="${label}" aria-expanded="${!sidebarCollapsed}" aria-controls="sidebar-navigation">${icon(sidebarCollapsed?'arrowright':'arrowleft')}</button>`}
function toggleSidebar(){sidebarCollapsed=!sidebarCollapsed;try{localStorage.setItem('rotations-sidebar-collapsed',String(sidebarCollapsed))}catch{}document.documentElement.dataset.sidebar=sidebarCollapsed?'collapsed':'expanded';const button=$('[data-act=toggle-sidebar]');if(button){button.innerHTML=icon(sidebarCollapsed?'arrowright':'arrowleft');button.title=translateText(sidebarCollapsed?'Развернуть меню':'Свернуть меню');button.setAttribute('aria-label',button.title);button.setAttribute('aria-expanded',String(!sidebarCollapsed))}}
async function api(path,data,method='POST',binary=false){
  const response=await fetch('/api/'+path,{method:data===undefined?'GET':method,headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data===undefined?undefined:JSON.stringify(data)});
  if(!response.ok){let p=await response.json().catch(()=>({error:'Сервер недоступен.'}));if(response.status===401&&path!=='login'){state=null;closeModal();renderLogin()}const error=new Error(p.error||'Не удалось сохранить.');error.status=response.status;throw error}
  return binary?response.blob():response.json();
}
function toast(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').className='visible'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',4500)}
async function load(){if(!Object.keys(countryCatalog).length)countryCatalog=await api('countries');if(!appVersion){const release=await api('version');appVersion=release.version}state=await api('data');csrf=state.csrf;if(!state.projects.some(p=>p.id===projectId))projectId=state.projects[0]?.id??null;render()}
