function openEvent(employeeId,record=null){if(isSecretary()&&record&&!['outbound','return'].includes(record.kind))return modal('Просмотр события',`<p>${esc(eventLabels[record.kind])} · ${fmt(record.date)}</p><div class="notice">Секретарь может изменять только перелёты.</div>`);const e=state.employees.find(e=>e.id===employeeId);modal(record?'Событие: '+eventLabels[record.kind]:'Новое событие',`<div class="worker-select-note">${esc(fullName(e))}</div><div class="form-grid">${select('kind','Тип события',Object.entries(eventLabels).filter(([kind])=>!isSecretary()||['outbound','return'].includes(kind)),record?.kind||'outbound')}${select('transport','Транспорт',Object.entries(transportLabels),record?.transport||'unknown')}${select('ticket_bought','Статус билета',[[0,'Билет не куплен'],[1,'Билет куплен']],record?.ticket_bought||0)}${input('date','Дата',record?.date||todayISO(),'date','required')}${input('time','Время (необязательно)',record?.time||'','time')}${input('route','Маршрут',record?.route||'','text','placeholder="VNO → ARN"')}${input('flight','Номер рейса',record?.flight||'','text','placeholder="SK 1741"')}${notes(record?.notes)}</div>${footer('Сохранить',record?'<button type="button" class="danger" data-act="remove-event">Удалить событие</button>':'')}`,data=>saved('events',{...data,ticket_bought:Number(data.ticket_bought),employee_id:employeeId,project_id:projectId,...(record?{id:record.id,version:record.version}:{})}),{'remove-event':()=>modal('Удалить событие?',`<p>${esc(eventLabels[record.kind])} · ${fmt(record.date)}</p>${footer('Удалить')}`,()=>saved('events',{id:record.id,version:record.version},'DELETE'))});}
function renderProjects(){const admin=effectiveRole()==='admin';$('#content').innerHTML=`<div class="page-head"><div><h1>Проекты</h1><div class="subheading">Адреса, руководители и сроки работы</div></div>${admin?'<div class="head-actions"><button class="primary" data-act="new-project">'+icon('plus')+' Проект</button></div>':''}</div><div class="list-grid">${state.projects.map(p=>`<article class="card"><div class="card-top">${icon('building')}<div class="project-card-badges"><span class="project-worker-count" title="${esc(translateText(projectEmployees(p.id).length+' работников'))}" aria-label="${esc(translateText(projectEmployees(p.id).length+' работников'))}">${icon('worker')}<span>${projectEmployees(p.id).length}</span></span><span class="pill ${p.status==='archived'?'gray':''}">${statusLabels[p.status]}</span></div></div><h3 style="margin-top:15px">${esc(p.name)}</h3><p>${esc(projectLocation(p))}<br>${fmt(p.start)} — ${fmt(p.end)}</p><div class="muted" style="font-size:12px;line-height:1.7">Руководители и секретари: ${esc(state.managers.filter(m=>m.project_id===p.id).map(m=>m.name).join(', ')||'Не назначены')}</div>${p.notes?`<p>${esc(p.notes)}</p>`:''}<div class="actions"><button data-act="project-schedule" data-id="${p.id}">Открыть график</button>${admin?`<button data-act="project-edit" data-id="${p.id}" title="Изменить проект">${icon('edit')}</button>`:''}</div></article>`).join('')||'<div class="empty">Проекты пока не созданы.</div>'}</div>`}
function openProject(id){const old=state.projects.find(p=>p.id===id),managers=state.users.filter(u=>['manager','secretary'].includes(u.role)&&u.active);const chosen=state.managers.filter(m=>m.project_id===id).map(m=>m.user_id);modal(old?'Изменить проект':'Новый проект',`<div class="form-grid"><div class="full">${input('name','Название проекта',old?.name||'','text','required')}</div>${countryInput(old?.country||'LT')}${select('status','Статус',[['active','Активный'],['archived','В архиве']],old?.status||'active')}<div class="full">${input('address','Адрес проекта',old?.address||'','text','required maxlength="2000"')}</div>${input('start','Начало проекта',old?.start||todayISO(),'date','required')}${input('end','Окончание проекта',old?.end||add(todayISO(),365),'date','required')}<label class="full">Руководители и секретари<div class="checkbox-list">${managers.map(u=>`<label class="check-label"><input type="checkbox" name="manager_ids" value="${u.id}" ${chosen.includes(u.id)?'checked':''}>${esc(u.name)} · ${roleLabels[u.role]}</label>`).join('')||'<span>Активных руководителей пока нет.</span>'}</div></label>${notes(old?.notes)}</div><div class="notice" style="margin-top:18px">При архивировании назначения и история графика сохраняются.</div>${footer()}`,(data,form)=>{const country=countryCode(data.country);if(!country)throw new Error('Выберите страну из списка.');return saved('projects',{...data,country,manager_ids:new FormData(form).getAll('manager_ids').map(Number),...(old?{id:old.id,version:old.version}:{})})})}
let employeesStatus='active',employeesSearch='';
function employeeNameMatches(employee,query){const normalize=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('lt');const name=normalize(fullName(employee));return normalize(query).trim().split(/\s+/).every(part=>name.includes(part))}
function filterEmployeeRows(){const visible=state.employees.filter(e=>(!employeesStatus||e.status===employeesStatus)&&employeeNameMatches(e,employeesSearch));const ids=new Set(visible.map(e=>String(e.id)));$$('[data-employee-row]').forEach(row=>row.hidden=!ids.has(row.dataset.employeeRow));$('#employees-no-results').hidden=visible.length>0}

function renderEmployees(){const admin=effectiveRole()==='admin';$('#content').innerHTML=`<div class="page-head"><div><h1>Работники</h1><div class="subheading">Карточки команды и история назначений</div></div>${admin?'<button class="primary" data-act="new-employee">'+icon('plus')+' Добавить работника</button>':''}</div><div class="employee-filters"><div class="search">${icon('search')}<input id="employees-search" type="search" placeholder="Найти работника…" aria-label="Поиск работника" value="${esc(employeesSearch)}"></div><select id="employees-status" aria-label="Фильтр по статусу"><option value="active" ${employeesStatus==='active'?'selected':''}>Активные работники</option><option value="archived" ${employeesStatus==='archived'?'selected':''}>Неактивные работники</option><option value="" ${!employeesStatus?'selected':''}>Все работники</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Работник</th><th>Специальность</th><th>Проекты / назначения</th><th>Статус</th><th></th></tr></thead><tbody>${state.employees.filter(e=>!employeesStatus||e.status===employeesStatus).map(e=>`<tr data-employee-row="${e.id}"><td><div class="table-title">${employeeAvatar(e)}<div>${esc(fullName(e))}${leadershipBadge(e)}<small>${esc(e.contact)}</small></div></div></td><td>${esc(e.specialty)}</td><td>${state.assignments.filter(a=>a.employee_id===e.id).map(a=>`<div>${esc(state.projects.find(p=>p.id===a.project_id)?.name)} · ${employeeTeam(e.id,a.project_id)?esc(employeeTeam(e.id,a.project_id).name):'Без команды'}<small>${fmt(a.start)} — ${fmt(a.end)}${a.active===0?' · Неактивное назначение':''} ${admin?`<button class="icon" data-act="assignment-edit" data-id="${a.id}" title="Изменить назначение">${icon('edit')}</button>`:''}</small></div>`).join('')||'<span class="muted">Не назначен</span>'}</td><td><span class="pill ${e.status==='archived'?'gray':''}">${e.status==='active'?'Активный':'Неактивный'}</span></td><td>${admin?`<button class="icon" data-act="employee-edit" data-id="${e.id}" title="Изменить работника">${icon('edit')}</button> <button class="${e.status==='active'?'danger':'primary'}" data-act="${e.status==='active'?'deactivate-employee':'restore-employee'}" data-id="${e.id}">${e.status==='active'?'Удалить из списка':'Вернуть в список'}</button>`:`<button class="icon" data-act="employee-details" data-id="${e.id}" title="Карточка работника">${icon('info')}</button>`}</td></tr>`).join('')}</tbody></table><div id="employees-no-results" class="empty" hidden>Нет работников, соответствующих фильтрам.</div></div>`;$('#employees-status').onchange=e=>{employeesStatus=e.target.value;renderEmployees()};$('#employees-search').oninput=e=>{employeesSearch=e.target.value;filterEmployeeRows()};filterEmployeeRows()}
function employeeAvatar(employee){return `<span class="avatar">${employee.has_photo?`<img class="employee-photo" src="/api/employees/${employee.id}/photo?v=${employee.version}" alt="${esc(fullName(employee))}">`:esc(initials(employee))}</span>`}
async function readEmployeePhoto(file){try{return await readScreenshot(file)}catch(error){throw new Error(error.message.replace('Прикрепите корректный скриншот','Прикрепите корректную фотографию').replace('Скриншот не должен','Фотография не должна').replace('скриншот','фотографию'))}}
function openEmployee(id,pid=null){
 let photoRemoved=false;
 const old=state.employees.find(e=>e.id===id);
 if(effectiveRole()!=='admin')return modal(fullName(old),`${employeeAvatar(old)}<p>${esc(old.specialty)}</p><p>${esc(old.contact)}</p><p>${esc(old.notes)}</p>`);
 const projects=state.projects.filter(p=>p.status==='active');
 const specialties=['Electrician','Mechanic','Welder'];
 const specialtyActions=Object.fromEntries(specialties.map((value,index)=>['specialty-preset-'+index,()=>{const field=$('[name=specialty]');field.value=value;field.focus()}]));
 modal(old?'Карточка работника':'Новый работник',`<div class="employee-photo-editor"><div id="employee-photo-preview">${old?employeeAvatar(old):'<span class="avatar">'+icon('users')+'</span>'}</div><div><label>Фотография работника<input id="employee-photo-file" type="file" accept="image/png,image/jpeg,image/webp"></label><small class="muted">PNG, JPEG или WebP · до 4 МБ</small><button type="button" data-act="remove-employee-photo">Убрать фотографию</button></div></div><div class="form-grid">${input('first_name','Имя',old?.first_name||'','text','required')}${input('last_name','Фамилия',old?.last_name||'','text','required')}${input('specialty','Специальность',old?.specialty||'','text','required')}<div class="specialty-presets">${specialties.map((value,index)=>`<button type="button" data-act="specialty-preset-${index}">${value}</button>`).join('')}</div><div class="full">${select('leadership','Роль работника',[['none','Работник'],['team_leader','Team Leader (TL)'],['work_manager','Work Manager (WM)']],old?.leadership||'none')}</div>${select('status','Статус',[['active','Активный'],['archived','Неактивный']],old?.status||'active')}<div class="full">${input('contact','Контактные данные',old?.contact||'')}</div>${notes(old?.notes)}${!old&&pid?`<input type="hidden" name="registration_project" value="${pid}"><div class="full notice">${esc(projects.find(p=>p.id===pid)?.name||'')}</div><div class="full" id="registration-assignment"></div>`:''}</div>${footer(!old&&pid?'Добавить без ротации':'Сохранить',old?'<button type="button" class="danger" data-act="delete-employee-card">Удалить карточку</button>':'')}`,async data=>{
  const payload={...data,...(old?{id:old.id,version:old.version}:{})};
  const file=$('#employee-photo-file').files[0];if(file)payload.photo=await readEmployeePhoto(file);else if(photoRemoved)payload.photo=null;
  if(!old&&data.registration_project)payload.assignment={project_id:Number(data.registration_project),start:data.assignment_start,end:data.assignment_end,team_id:data.registration_team?Number(data.registration_team):null};
  return saved('employees',payload);
 },{...specialtyActions,'delete-employee-card':()=>confirmDeleteEmployee(old),'remove-employee-photo':()=>{photoRemoved=true;$('#employee-photo-file').value='';$('#employee-photo-preview').innerHTML=old?`<span class="avatar">${esc(initials(old))}</span>`:'<span class="avatar">'+icon('users')+'</span>'}});
 $('#employee-photo-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;$('#modal-error').textContent='';try{const data=await readEmployeePhoto(file);if($('#employee-photo-file')?.files[0]!==file)return;photoRemoved=false;$('#employee-photo-preview').innerHTML=`<span class="avatar"><img class="employee-photo" src="${esc(data)}" alt="Фотография работника"></span>`}catch(error){event.target.value='';$('#modal-error').textContent=translateText(error.message)}};
 if(!old&&pid){const draw=()=>{const p=projects.find(p=>p.id===pid);$('#registration-assignment').innerHTML=p?`<div class="form-grid">${input('assignment_start','Начало назначения',p.start,'date','required')}${input('assignment_end','Окончание назначения',p.end,'date','required')}<div class="full">${select('registration_team','Команда',[['','Без команды'],...(state.teams||[]).filter(t=>t.status!=='archived'&&t.project_id===p.id).map(t=>[t.id,t.name])],'')}</div></div>`:''};draw()}
}
function confirmDeleteEmployee(employee){
 if(effectiveRole()!=='admin')return;
 modal('Удалить карточку работника?',`<p>${esc(fullName(employee))}</p><div class="notice warn">Карточка, назначения, график, поездки и фотография будут удалены без возможности восстановления. Запись об удалении останется в истории.</div>${input('confirm_word','Введите DELETE для подтверждения','','text','required pattern="DELETE" autocomplete="off" placeholder="DELETE"')}${footer('Удалить карточку')}`,data=>saved('employees',{id:employee.id,version:employee.version,schedule_version:employee.schedule_version,confirm:data.confirm_word},'DELETE'));
}
function openAssignment(employeeId=null,pid=null,id=null){const old=state.assignments.find(a=>a.id===id);const employees=state.employees.filter(e=>e.status==='active'),projects=state.projects.filter(p=>p.status==='active');if(!employees.length||!projects.length)return toast('Нужен активный проект и активный работник.',true);pid=old?.project_id||pid||projects[0].id;const p=projects.find(p=>p.id===pid);if(!p)return toast('Сначала восстановите проект.',true);modal(old?'Изменить назначение':'Назначить работника',`<div class="form-grid"><div class="full">${select('employee_id','Работник',employees.map(e=>[e.id,fullName(e)]),old?.employee_id||employeeId||employees[0].id)}</div><div class="full">${select('project_id','Проект',projects.map(p=>[p.id,p.name]),pid)}</div>${input('start','Начало назначения',old?.start||p.start,'date','required')}${input('end','Окончание назначения',old?.end||p.end,'date','required')}</div><label class="check-label"><input name="assignment_active" type="checkbox" ${!old||old.active!==0?'checked':''}>Назначение активно</label><div class="notice" style="margin-top:18px">Назначения на разные объекты не могут пересекаться. Чтобы завершить назначение, измените дату окончания, сохраняя исторические периоды.</div>${footer(old?'Сохранить':'Добавить без ротации')}`,(data,form)=>saved('assignments',{...numeric(data,['project_id','employee_id']),active:$('[name=assignment_active]',form).checked,...(old?{id:old.id,version:old.version}:{})}));if(old){$('select[name=employee_id]').disabled=true;$('select[name=project_id]').disabled=true;modalSubmit=(data,form)=>saved('assignments',{...data,active:$('[name=assignment_active]',form).checked,employee_id:old.employee_id,project_id:old.project_id,id:old.id,version:old.version})}}
function renderUsers(){$('#content').innerHTML=`<div class="page-head"><div><h1>Учётные записи</h1><div class="subheading">Доступ руководителей и секретарей к проектам</div></div><button class="primary" data-act="new-user">${icon('plus')} Добавить пользователя</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Пользователь</th><th>Роль</th><th>Проекты</th><th>Доступ</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${esc(u.name)}<small>${esc(u.username)}</small></td><td>${roleLabels[u.role]}</td><td>${u.role==='admin'?'Все проекты':esc(state.managers.filter(m=>m.user_id===u.id).map(m=>state.projects.find(p=>p.id===m.project_id)?.name).join(', ')||'Не назначены')}</td><td><span class="pill ${u.active?'':'gray'}">${u.active?'Активен':'Отключён'}</span></td><td><button class="icon" data-act="user-edit" data-id="${u.id}" title="Изменить пользователя">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`}
function openUser(id){const old=state.users.find(u=>u.id===id);modal(old?'Изменить учётную запись':'Новый пользователь',`<div class="form-grid"><div class="full">${input('name','Имя и фамилия',old?.name||'','text','required')}</div><div class="full">${select('role','Роль',old?.role==='admin'?[['admin','Администратор']]:[['manager','Руководитель проекта'],['secretary','Секретарь']],old?.role||'manager')}</div>${input('username','Логин',old?.username||'','text','required minlength="3" autocomplete="off"')}${input('password',old?'Новый пароль (необязательно)':'Пароль', '', 'password', 'minlength="10" maxlength="256" autocomplete="new-password" '+(old?'':'required'))}<label class="check-label full"><input type="checkbox" name="active" ${!old||old.active?'checked':''}>Учётная запись активна</label></div><div class="notice" style="margin-top:18px">Учётные записи создаются только для руководителей проектов и секретарей. Работники не имеют доступа к системе. Проекты назначаются в карточке проекта. Отключение немедленно завершит все сессии пользователя.</div>${footer()}`,(data,form)=>saved('users',{...data,active:$('[name=active]',form).checked,...(old?{id:old.id,version:old.version}:{})}))}
function openPassword(){modal('Сменить пароль',`<div class="form-stack">${input('current','Текущий пароль','','password','required autocomplete="current-password"')}${input('password','Новый пароль','','password','required minlength="10" maxlength="256" autocomplete="new-password"')}${input('confirmation','Повторите новый пароль','','password','required minlength="10" autocomplete="new-password"')}</div><div class="notice" style="margin-top:18px">После смены пароля потребуется войти заново.</div>${footer('Сменить пароль')}`,async data=>{if(data.password!==data.confirmation)throw new Error('Новые пароли не совпадают.');await api('password',data);closeModal();state=null;renderLogin();toast('Пароль изменён. Войдите с новым паролем.')})}
function openExport(){const range=periodRange();const p=currentProject();modal('Экспорт графика в PDF',`<div class="form-grid"><div class="full">${select('project_id','Проект',state.projects.map(p=>[p.id,p.name]),p.id)}</div>${input('start','Начало периода',range.start,'date','required')}${input('end','Окончание периода',range.end,'date','required')}${select('paper','Бумага',[['A4','A4 · альбомная'],['A3','A3 · альбомная']],'A4')}${select('selection','Работники',[['all','Все работники'],['selected','Выбранные работники']],'all')}<div class="full" id="export-employees"></div><label class="check-label full"><input type="checkbox" name="include_photos">Включить фотографии работников</label><label class="check-label full"><input type="checkbox" name="include_notes" checked>Включить примечания</label><label class="check-label full"><input type="checkbox" name="include_events" checked>Включить перелёты и события</label></div><div class="notice" style="margin-top:18px">Полный диапазон будет разбит на читаемые страницы. Имена и заголовки повторяются; детали перелётов и примечания — в приложении.</div>${footer('Скачать PDF')}`,async(data,form)=>{const blob=await api('export',{...numeric(data,['project_id']),language,include_photos:$('[name=include_photos]',form).checked,include_notes:$('[name=include_notes]',form).checked,include_events:$('[name=include_events]',form).checked,employee_ids:data.selection==='selected'?new FormData(form).getAll('employee_ids').map(Number):null},'POST',true);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='График-ротаций-'+data.start+'_'+data.end+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);closeModal();toast('PDF сформирован')});
 const draw=()=>{let pid=Number($('[name=project_id]').value);$('#export-employees').innerHTML=$('[name=selection]').value==='selected'?`<div class="checkbox-list">${projectEmployees(pid).map(e=>`<label class="check-label"><input type="checkbox" name="employee_ids" value="${e.id}" checked>${esc(fullName(e))}</label>`).join('')}</div>`:''};$('[name=project_id]').onchange=draw;$('[name=selection]').onchange=draw;draw();
}
let auditRecords=[];
async function renderAudit(){const content=$('#content');content.innerHTML='<div class="page-head"><div><h1>История изменений</h1><div class="subheading">Кто, когда и что изменил</div></div></div><div id="history-body" class="empty">Загрузка…</div>';try{auditRecords=await api('audit');if(view!=='audit')return;$('#history-body').className='table-wrap';$('#history-body').innerHTML=`<table class="data-table"><thead><tr><th>Дата и время</th><th>Пользователь</th><th>Действие</th><th>Проект</th><th></th></tr></thead><tbody>${auditRecords.map(a=>`<tr><td>${esc(new Date(a.created_at.replace(' ','T')+'Z').toLocaleString('ru-RU'))}</td><td>${esc(a.user_name||'Система')}</td><td>${esc(a.action)}</td><td>${esc(state.projects.find(p=>p.id===a.project_id)?.name||'Общие данные')}</td><td><button data-act="audit-detail" data-id="${a.id}">Подробности</button></td></tr>`).join('')}</tbody></table>`}catch(e){toast(e.message,true)}}
function auditDetail(id){const a=auditRecords.find(a=>a.id===id);const labels={first_name:'Имя',last_name:'Фамилия',name:'Название',start:'Начало',end:'Окончание',kind:'Статус / событие',notes:'Примечание',manual:'Ручная правка',date:'Дата',time:'Время',address:'Адрес проекта',country:'Страна',route:'Маршрут',flight:'Рейс',transport:'Транспорт',ticket_bought:'Статус билета',specialty:'Специальность',status:'Статус',active:'Активен',username:'Логин',contact:'Контакты',role:'Роль',team_id:'Команда'};const describe=json=>{if(!json)return'—';let value=JSON.parse(json);const format=x=>Object.entries(x).filter(([k])=>labels[k]).map(([k,v])=>labels[k]+': '+(k==='ticket_bought'?(v?'Билет куплен':'Билет не куплен'):k==='transport'?transportLabels[v]:k==='role'?roleLabels[v]:k==='team_id'?(state.teams?.find(t=>t.id===v)?.name||'Без команды'):(kindLabels[v]||eventLabels[v]||statusLabels[v]||v))).join('\n');return Array.isArray(value)?value.map(format).join('\n\n'):format(value)||JSON.stringify(value)};modal(a.action,`<p class="muted">${esc(a.user_name)} · ${esc(a.created_at)} UTC</p><p>До изменения</p><div class="audit-details">${esc(describe(a.before_json))}</div><p>После изменения</p><div class="audit-details">${esc(describe(a.after_json))}</div>`)}
async function action(name,id,event){
 if(modalActions[name])return modalActions[name]();
 switch(name){case'toggle-sidebar':toggleSidebar();break;case'close':closeModal();break;case'nav':view=id;render();break;case'refresh':await load();toast('Данные обновлены');break;case'reload-modal':closeModal();await load();break;case'logout':await api('logout',{});state=null;renderLogin();break;case'password':openPassword();break;case'export':openExport();break;case'plan':pickWorker(isSecretary()?openPeriod:openCycle);break;case'worker-tools':openTools(Number(id));break;case'period':if(!suppressClick){let p=state.periods.find(p=>p.id===Number(id));openPeriod(p.employee_id,p)}break;case'event':{let e=state.events.find(e=>e.id===Number(id));openEvent(e.employee_id,e);break}case'prev':case'next':{let d=dt(anchor);d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+(name==='prev'?-1:1)*(scale==='month'?1:scale==='quarter'?3:12));anchor=iso(d);renderSchedule();break}case'today':anchor=todayISO();renderSchedule();if(scale!=='month'){let r=periodRange();$('#calendar').scrollLeft=Math.max(0,(dt(anchor)-dt(r.start))/86400000*(scale==='year'?14:22)-200)}break;case'scale':scale=id;renderSchedule();break;case'new-project':openProject();break;case'project-edit':openProject(Number(id));break;case'project-schedule':projectId=Number(id);view='schedule';render();break;case'assign-project':openAssignment(null,Number(id));break;case'assign-employee':openAssignment(Number(id));break;case'assignment-edit':openAssignment(null,null,Number(id));break;case'deactivate-employee':deactivateEmployee(Number(id));break;case'restore-employee':await restoreEmployee(Number(id));break;case'new-employee':openEmployee();break;case'employee-edit':case'employee-details':openEmployee(Number(id));break;case'theme':toggleTheme();break;case'add-project-worker':addProjectWorker();break;case'team-add':openTeam(Number(id));break;case'team-delete':deleteTeam(Number(id));break;case'new-team':openTeam();break;case'team-edit':openTeam(Number(id));break;case'worker-team':openWorkerTeam(Number(id));break;case'new-user':openUser();break;case'user-edit':openUser(Number(id));break;case'audit-detail':auditDetail(Number(id));break;case'send-feedback':openFeedback();break;case'feedback-detail':openFeedbackDetail(Number(id));break;case'feedback-delete':deleteFeedback(Number(id));break;case'feedback-prev':feedbackPage=Math.max(1,feedbackPage-1);await renderFeedback();break;case'feedback-next':feedbackPage++;await renderFeedback();break;
 }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b&&!b.disabled)Promise.resolve(action(b.dataset.act,b.dataset.id,e)).catch(err=>toast(err.message,true))});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focusable=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)', $('.modal'));let first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
load().catch(e=>{renderLogin();if(e.status!==401)toast('Не удалось подключиться к серверу.',true)});

function deactivateEmployee(id){const employee=state.employees.find(e=>e.id===id);modal('Сделать работника неактивным?',`<p>${esc(fullName(employee))}</p><div class="notice warn">Работник исчезнет из активного списка. Его назначения, ротации и история сохранятся. Его можно вернуть через фильтр «Неактивные работники».</div>${footer('Удалить из списка')}`,()=>saved('employees',{...employee,status:'archived'}))}
async function restoreEmployee(id){const employee=state.employees.find(e=>e.id===id);await saved('employees',{...employee,status:'active'})}
let selectedPalette=null,paletteBusy=false;
function selectPalette(kind){selectedPalette=selectedPalette===kind?null:kind;$$('[data-palette]').forEach(b=>{b.classList.toggle('selected',b.dataset.palette===selectedPalette);b.setAttribute('aria-pressed',String(b.dataset.palette===selectedPalette))});if(selectedPalette)toast(translateText('Выберите день в строке работника'))}
function dropPosition(x,y){const track=document.elementsFromPoint(x,y).map(e=>e.closest('.row-track')).find(Boolean);if(!track)return null;const rect=track.getBoundingClientRect(),days=periodRange().days,width=scale==='month'?28:scale==='quarter'?22:14;const index=Math.floor((x-rect.left)/width);if(index<0||index>=days.length)return null;const employee=state.employees.find(e=>e.id===Number(track.dataset.employee));if(employee?.status!=='active'||currentProject()?.status!=='active')return null;return{track,employee,date:days[index],left:index*width,width}}
function clearDropPreview(){$$('.drop-preview').forEach(el=>el.remove());document.body.classList.remove('palette-dragging')}
function paintDrop(position,kind){$$('.drop-preview').forEach(el=>el.remove());if(!position)return;const preview=document.createElement('span');preview.className='drop-preview '+kind;preview.style.left=position.left+'px';preview.style.width=position.width+'px';preview.textContent=kind==='outbound'?'✈':'+';position.track.append(preview)}
async function addPaletteItem(position,kind){if(paletteBusy)return;paletteBusy=true;try{const employee=position.employee;const common={project_id:projectId,employee_id:employee.id};let trip;if(kind==='outbound'){trip=await api('events',{...common,date:position.date,kind,transport:'unknown',ticket_bought:0,time:'',route:'',flight:'',notes:''})}else{await api('periods',{...common,start:position.date,end:position.date,kind,schedule_version:employee.schedule_version,notes:''})}await load();toast(translateText(kind==='outbound'?'Событие добавлено':'Статус добавлен'));if(trip?.id)openEvent(employee.id,state.events.find(ev=>ev.id===trip.id)||trip)}catch(error){toast(translateText(error.message),true);if(error.status===409)await load()}finally{paletteBusy=false}}
function setupPalette(){
 $$('[data-palette]').forEach(button=>{
  button.onclick=()=>{if(!suppressClick)selectPalette(button.dataset.palette)};
  button.onpointerdown=event=>{if(event.button!==0||paletteBusy)return;const kind=button.dataset.palette;const x=event.clientX,y=event.clientY;let moved=false,position=null;button.setPointerCapture(event.pointerId);
   function move(e){if(Math.hypot(e.clientX-x,e.clientY-y)>5)moved=true;if(!moved)return;document.body.classList.add('palette-dragging');position=dropPosition(e.clientX,e.clientY);paintDrop(position,kind)}
   function cleanup(){button.removeEventListener('pointermove',move);button.removeEventListener('pointerup',finish);button.removeEventListener('pointercancel',cancel);clearDropPreview()}
   function finish(e){position=dropPosition(e.clientX,e.clientY);cleanup();if(!moved)return;suppressClick=true;setTimeout(()=>suppressClick=false,100);if(position)addPaletteItem(position,kind)}
   function cancel(){cleanup()}
   button.addEventListener('pointermove',move);button.addEventListener('pointerup',finish);button.addEventListener('pointercancel',cancel);
  };
 });
 $('#calendar')?.addEventListener('click',event=>{if(!selectedPalette||event.target.closest('button'))return;const position=dropPosition(event.clientX,event.clientY);if(position)addPaletteItem(position,selectedPalette)});
}

function openWorkerTeam(employeeId){const e=state.employees.find(e=>e.id===employeeId);const membership=(state.team_members||[]).find(m=>m.project_id===projectId&&m.employee_id===employeeId);modal('Команда работника',`<p>${esc(fullName(e))}</p><div class="form-stack">${select('team_id','Команда',[['','Без команды'],...(state.teams||[]).filter(t=>t.status!=='archived'&&t.project_id===projectId).map(t=>[t.id,t.name])],membership?.team_id||'')}</div>${footer()}`,data=>saved('team-members',{project_id:projectId,employee_id:employeeId,team_id:data.team_id?Number(data.team_id):null,version:membership?.version||0}))}
function openTeam(id,pid=projectId){
 const old=(state.teams||[]).find(t=>t.id===id);pid=old?.project_id||pid;const projects=state.projects.filter(p=>p.status==='active');
 if(effectiveRole()!=='admin'){const members=state.team_members.filter(m=>m.team_id===id).map(m=>state.employees.find(e=>e.id===m.employee_id)).filter(Boolean);return modal(old?.name||'Команда',`<div class="preview-list">${members.map(e=>`<div>${esc(fullName(e))} · ${esc(e.specialty)}</div>`).join('')||'<div>В команде пока нет работников.</div>'}</div>`)}
 if(!projects.length)return toast('Сначала создайте активный проект.',true);
 pid=pid||projects[0].id;
 modal(old?'Изменить команду':'Новая команда',`<div class="form-stack">${input('name','Название команды',old?.name||'','text','required')}<div class="notice">${esc(state.projects.find(p=>p.id===pid)?.name||'')}</div><label>Работники команды<div id="team-workers" class="checkbox-list"></div></label></div><div class="notice" style="margin-top:18px">У работника одна команда в каждом проекте. При выборе работника из другой команды он будет перенесён в эту команду.</div>${footer('Сохранить',old?`<button type="button" class="danger" data-act="delete-current-team">Удалить команду</button>`:'')}`,async(data,form)=>{
  const project=pid;const selected=new FormData(form).getAll('team_employee').map(Number);
  const previous=old?state.team_members.filter(m=>m.team_id===old.id).map(m=>m.employee_id):[];
  const changed=[...new Set([...previous,...selected])].map(employee_id=>({employee_id,selected:selected.includes(employee_id),version:state.team_members.find(m=>m.project_id===project&&m.employee_id===employee_id)?.version||0}));
  await saved('teams',{name:data.name,project_id:project,members:changed,...(old?{id:old.id,version:old.version}:{})});
 },{'delete-current-team':()=>deleteTeam(old.id)});
 const draw=()=>{const project=pid;$('#team-workers').innerHTML=projectEmployees(project).map(e=>{const team=employeeTeam(e.id,project);return`<label class="check-label"><input type="checkbox" name="team_employee" value="${e.id}" ${team?.id===old?.id&&old?'checked':''}>${esc(fullName(e))}${team?' · '+esc(team.name):''}${e.status==='archived'?' · Неактивный':''}</label>`}).join('')||'<span>Сначала назначьте работников на проект.</span>'};draw();
}

const leadershipBadge=employee=>employee.leadership==='team_leader'?'<span class="leadership-badge tl" title="Team Leader">TL</span>':employee.leadership==='work_manager'?'<span class="leadership-badge wm" title="Work Manager">WM</span>':'';
function dailyOnSiteCount(date){return projectEmployees().filter(e=>e.status==='active'&&!state.events.some(ev=>ev.employee_id===e.id&&ev.project_id===projectId&&ev.date===date&&isTravel(ev))&&state.assignments.some(a=>a.employee_id===e.id&&a.project_id===projectId&&a.active!==0&&a.start<=date&&a.end>=date)).filter(e=>{const p=state.periods.filter(p=>p.employee_id===e.id&&p.project_id===projectId&&p.start<=date&&p.end>=date).sort((a,b)=>(b.layer||0)-(a.layer||0))[0];return p?.kind==='work'}).length}
function addProjectWorker(){modal('Добавить работника в проект',`<div class="tools"><button type="button" data-act="existing-worker">${icon('users')} Выбрать из списка работников</button><button type="button" data-act="new-project-worker">${icon('plus')} Создать карточку работника</button></div>`,null,{'existing-worker':()=>openAssignment(null,projectId),'new-project-worker':()=>openEmployee(undefined,projectId)})}
function deleteTeam(id){const team=state.teams.find(t=>t.id===id);const count=state.team_members.filter(m=>m.team_id===id).length;modal('Удалить команду',`<p>${esc(team.name)} · ${count} работников</p><div class="notice">Карточки работников и история сохранятся при любом варианте.</div><div class="form-stack">${select('mode','Что сделать с работниками',[['keep_workers','Удалить команду, оставить работников на объекте'],['remove_workers','Удалить команду и убрать работников из проекта']],'keep_workers')}</div>${footer('Удалить команду')}`,data=>saved('teams',{id:team.id,version:team.version,mode:data.mode},'DELETE'))}
let theme='light';
try{theme=localStorage.getItem('rotations-theme')==='dark'?'dark':'light'}catch{}
function applyTheme(){document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme}
function themeButton(){return `<button class="theme-toggle" data-act="theme" title="${theme==='dark'?'Светлая тема':'Тёмная тема'}" aria-label="${theme==='dark'?'Светлая тема':'Тёмная тема'}">${theme==='dark'?'☀':'☾'}</button>`}
function toggleTheme(){theme=theme==='dark'?'light':'dark';try{localStorage.setItem('rotations-theme',theme)}catch{}applyTheme();$$('[data-act=theme]').forEach(button=>{button.innerHTML=theme==='dark'?'☀':'☾';button.title=translateText(theme==='dark'?'Светлая тема':'Тёмная тема');button.setAttribute('aria-label',button.title)})}
applyTheme();

function readScreenshot(file){return new Promise((resolve,reject)=>{if(!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('Прикрепите корректный скриншот PNG, JPEG или WebP.'));if(file.size>4*1024*1024)return reject(new Error('Скриншот не должен превышать 4 МБ.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Не удалось прочитать скриншот.'));reader.readAsDataURL(file)})}
function openFeedback(){
 const pid=view==='schedule'?projectId:null;
 modal('Обратная связь',`<p class="feedback-intro">Нашли ошибку или есть идея для улучшения?</p><div class="form-stack">${select('kind','Тип сообщения',[['bug','Ошибка'],['idea','Предложение']],'bug')}<label>Ваше сообщение<textarea name="message" required maxlength="5000" rows="5" placeholder="Опишите проблему или предложение…"></textarea></label><label>Скриншот (необязательно)<input id="feedback-file" type="file" accept="image/png,image/jpeg,image/webp"></label><small class="muted">PNG, JPEG или WebP · до 4 МБ</small><div id="feedback-preview"></div><div class="notice">Сообщение увидит только администратор.</div></div>${footer('Отправить')}`,async(data)=>{
 const file=$('#feedback-file').files[0];const screenshot=file?await readScreenshot(file):'';
 await api('feedback',{kind:data.kind,message:data.message,screenshot,project_id:pid});closeModal();toast(translateText('Спасибо! Отзыв отправлен администратору.'));
 },{'clear-feedback-file':()=>{$('#feedback-file').value='';$('#feedback-preview').innerHTML=''}});
 $('#feedback-file').onchange=async e=>{const file=e.target.files[0];$('#feedback-preview').innerHTML='';$('#modal-error').textContent='';if(!file)return;try{const data=await readScreenshot(file);if($('#feedback-file')?.files[0]!==file)return;$('#feedback-preview').innerHTML=`<img class="feedback-preview" src="${esc(data)}" alt="Скриншот"><button type="button" data-act="clear-feedback-file">Убрать скриншот</button>`}catch(error){e.target.value='';$('#modal-error').textContent=translateText(error.message)}};
}
let feedbackRecords=[],feedbackFilter='',feedbackPage=1,feedbackTotal=0,feedbackPageSize=50,feedbackRequest=0;
async function renderFeedback(){
 if(effectiveRole()!=='admin')return;
 const request=++feedbackRequest;
 $('#content').innerHTML='<div class="page-head"><div><h1>Отзывы</h1><div class="subheading">Ошибки и предложения пользователей · только для администратора</div></div></div><div id="feedback-body" class="empty">Загрузка…</div>';
 try{const result=await api('feedback?page='+feedbackPage+'&status='+encodeURIComponent(feedbackFilter));if(view!=='feedback'||request!==feedbackRequest)return;feedbackRecords=result.items;feedbackTotal=result.total;feedbackPage=result.page;feedbackPageSize=result.page_size;drawFeedback()}catch(error){if(view==='feedback'&&request===feedbackRequest)$('#feedback-body').textContent=translateText(error.message)}
}
function drawFeedback(){
 const records=feedbackRecords,pages=Math.max(1,Math.ceil(feedbackTotal/feedbackPageSize));
 $('#feedback-body').className='';$('#feedback-body').innerHTML=`<div class="employee-filters"><select id="feedback-filter" aria-label="Статус отзыва"><option value="" ${!feedbackFilter?'selected':''}>Все отзывы</option><option value="new" ${feedbackFilter==='new'?'selected':''}>Новые</option><option value="reviewed" ${feedbackFilter==='reviewed'?'selected':''}>Просмотренные</option></select><span class="muted">${feedbackTotal}</span><button data-act="feedback-prev" ${feedbackPage<=1?'disabled':''} title="Предыдущая страница">${icon('arrowleft')}</button><span>${feedbackPage} / ${pages}</span><button data-act="feedback-next" ${feedbackPage>=pages?'disabled':''} title="Следующая страница">${icon('arrowright')}</button></div><div class="feedback-list">${records.map(r=>`<article class="card feedback-card"><div class="feedback-card-top"><span class="pill ${r.kind==='bug'?'feedback-bug':''}">${r.kind==='bug'?'Ошибка':'Предложение'}</span><span class="feedback-status ${r.status==='new'?'is-new':''}">${r.status==='new'?'Новый':'Просмотрен'}</span><time>${esc(new Date(r.created_at.replace(' ','T')+'Z').toLocaleString())}</time></div><div class="feedback-author">${esc(r.user_name)} · ${esc(r.username)}${r.project_name?' · '+esc(r.project_name):''}</div><p class="feedback-text">${esc(r.message)}</p><div class="actions"><button data-act="feedback-detail" data-id="${r.id}">Подробности${r.has_screenshot?' · '+translateText('Скриншот'):''}</button><button class="icon danger" data-act="feedback-delete" data-id="${r.id}" title="Удалить отзыв" aria-label="Удалить отзыв">${icon('trash')}</button></div></article>`).join('')||'<div class="empty">Отзывов пока нет.</div>'}</div>`;$('#feedback-filter').onchange=e=>{feedbackFilter=e.target.value;feedbackPage=1;renderFeedback()};
}
function openFeedbackDetail(id){
 if(effectiveRole()!=='admin')return;const r=feedbackRecords.find(r=>r.id===id);if(!r)return;
 modal(r.kind==='bug'?'Ошибка':'Предложение',`<div class="feedback-author">${esc(r.user_name)} · ${esc(r.username)} · ${esc(new Date(r.created_at.replace(' ','T')+'Z').toLocaleString())}</div>${r.project_name?`<p>${esc(r.project_name)}</p>`:''}<p class="feedback-text">${esc(r.message)}</p>${r.has_screenshot?`<a href="/api/feedback/${r.id}/screenshot" target="_blank" rel="noopener"><img class="feedback-screenshot" src="/api/feedback/${r.id}/screenshot" alt="Скриншот"></a>`:''}<button type="button" class="danger" data-act="feedback-delete" data-id="${r.id}">Удалить отзыв</button>${footer(r.status==='new'?'Отметить просмотренным':'Вернуть в новые')}`,async()=>{await api('feedback-status',{id:r.id,version:r.version,status:r.status==='new'?'reviewed':'new'});closeModal();await renderFeedback()});
}
function deleteFeedback(id){
 if(effectiveRole()!=='admin')return;const record=feedbackRecords.find(item=>item.id===id);if(!record)return;
 modal('Удалить отзыв',`<p>${esc(record.user_name)} · ${esc(record.username)}</p><div class="notice">Отзыв и скриншот будут удалены без возможности восстановления.</div>${footer('Удалить отзыв')}`,async()=>{await api('feedback',{id:record.id,version:record.version},'DELETE');closeModal();await renderFeedback();toast(translateText('Отзыв удалён.'))});
}
